// @aue/content: official content (the built-in mod), the Stronghold-compatible content interface, the registry.
// M0.5: the skeleton's stage, operators and enemies, generated by @aue/data from ArknightsGameData (data/skeleton.json).
import skeleton from '../data/skeleton.json' with { type: 'json' };
import timings from '../data/timings.json' with { type: 'json' };
import { withTrait } from './traits.js';
import { skillDefOf } from './skills.js';
import { levelAt } from './levels.js';

/** A unit's attack timing from data/timings.json (攻击-2), when its skeleton gave one. @param {string} key */
function attackOf(key) {
  const t = /** @type {Record<string, { duration: number, hit: number }>} */ (timings.units)[key];
  return t ? { attack: { duration: t.duration, hit: t.hit } } : {};
}

/**
 * An extracted operator record as the simulation reads it: its branch trait (职业-7), its skill_table level as a
 * skill (技能-1) and its attack timing (攻击-2).
 * @param {string} key @param {any} o @returns {import('@aue/sim').OperatorDef}
 */
function operatorOf(key, o) {
  const { skillLevel, ...rest } = o;
  return { ...withTrait(rest), ...(skillLevel ? { skill: skillDefOf(skillLevel.id, skillLevel) } : {}), ...attackOf(key) };
}

/** The skeleton's content, as @aue/sim reads it. @type {import('@aue/sim').Content} */
export const skeletonContent = /** @type {any} */ ({
  ...skeleton,
  operators: Object.fromEntries(Object.entries(skeleton.operators).map(([k, o]) => [k, operatorOf(k, o)])),
  enemies: Object.fromEntries(Object.entries(skeleton.enemies).map(([k, e]) => [k, { ...e, ...attackOf(k) }])),
});

/**
 * A whole level at a difficulty (关卡-2) as @aue/sim's Content, with the skeleton's operators.
 * @param {string} id @param {import('./levels.js').Difficulty} difficulty @returns {import('@aue/sim').Content}
 */
export function levelContent(id, difficulty) {
  return /** @type {any} */ ({ ...levelAt(id, difficulty, attackOf), operators: skeletonContent.operators });
}

/** Where the attack timings come from: the skeletons' sources (攻击-2). */
export const timingSource = timings.source;

/** Where the skeleton's data comes from: the ArknightsGameData commit it was generated at. */
export const skeletonSource = skeleton.source;

export { skillDefOf, skillBehaviors } from './skills.js';
export { BRANCHES, coveredBranch, withTrait } from './traits.js';
export { LEVELS, levelAt } from './levels.js';
